    function deploy(string memory contractName, bytes memory constructorData, Options memory opts) internal returns (address) {
        if (opts.defender.useDefenderDeploy) {
            return DefenderDeploy.deploy(contractName, constructorData, opts.defender);
        }
        return _deploy(contractName, constructorData);
    }

    /**
     * @notice Deploys a contract using the provided contract name and constructor data.
     */
    function _deploy(string memory contractName, bytes memory constructorData) private returns (address) {
        string memory outDir = Utils.getOutDir();
        ContractInfo memory contractInfo = Utils.getContractInfo(contractName, outDir);
        string memory artifactPath = contractInfo.artifactPath;

        Vm vm = Vm(Utils.CHEATCODE_ADDRESS);
        string memory artifactJson = vm.readFile(artifactPath);
        bytes memory bytecode = vm.parseJsonBytes(artifactJson, ".bytecode.object");

        bytes memory deploymentBytecode = abi.encodePacked(bytecode, constructorData);
        address deployed = _deployFromBytecode(deploymentBytecode);

        if (deployed == address(0)) {
            revert(string(abi.encodePacked("Failed to deploy contract ", contractName)));
        }

        return deployed;
    }

    /**
     * @notice Deploys a contract from the provided bytecode.
     */
    function _deployFromBytecode(bytes memory bytecode) private returns (address) {
        address addr;
        assembly {
            addr := create(0, add(bytecode, 32), mload(bytecode))
        }
        return addr;
    }

    /**
     * @dev Helper to prank an address if it is not the zero address.
     */
    function _tryPrank(address tryCaller) private {
        if (tryCaller != address(0)) {
            Vm vm = Vm(Utils.CHEATCODE_ADDRESS);
            vm.prank(tryCaller);
        }
    }
